import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import * as lucide from 'lucide-react';

// PLAN:
// 1. Setup & Theming: Inject CSS variables based on the Design System (Colors, Typography, Spacing). Load Google Fonts (Bebas Neue, Archivo, JetBrains Mono).
// 2. State Management: `App` component manages `currentScreen` (dashboard_empty, trajectory_setup, calculating_state, interactive_map).
//    Also manages `trajectoryData` (the generated nodes), `activeNode` (for inspector), and user inputs (current, target, timeline).
// 3. Components:
//    - `Button`: Handles micro-interaction states (default, hover, active, loading, error, success) with framer-motion.
//    - `Input` / `Slider`: For trajectory setup.
//    - `TrajectoryNode`: Interactive circular nodes on the map with hover/active states.
// 4. Screens:
//    - `DashboardEmpty`: Welcome screen, CTA to start.
//    - `TrajectorySetup`: Form to input current state, target state, and timeline.
//    - `CalculatingState`: Shows pulsing animation and crossfading text. Triggers the AI call.
//    - `InteractiveMap`: Renders the generated nodes horizontally. Uses SVG for sequential connecting lines.
//    - `NodeInspector`: Slide-out panel (AnimatePresence) showing node details.
// 5. AI Integration:
//    - Endpoint: `/api/ai/gemini-compat`
//    - Trigger: Entering `calculating_state`.
//    - Prompt: Ask Gemini to act as an advisor and generate a JSON array of milestones based on current/target states.
//    - Handling: Parse JSON, handle errors with a fallback realistic dataset, transition to `interactive_map` on success.
// 6. Demo Controls: Fixed top-right panel to force screen transitions for easy review.

