const TrajectorySetup = ({ onGenerate, onBack }) => {
  const [current, setCurrent] = useState('');
  const [target, setTarget] = useState('');
  const [timeline, setTimeline] = useState(12);
  const [btnStatus, setBtnStatus] = useState('default');
  const sliderId = React.useId();

  const handleGenerate = async () => {
    if (!current || !target) {
      setBtnStatus('error');
      setTimeout(() => setBtnStatus('default'), 2000);
      return;
    }
    setBtnStatus('loading');
    // Simulate a brief local delay before handing off to the calculating screen
    setTimeout(() => {
      onGenerate({ current, target, timeline });
    }, 600);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
      style={{ maxWidth: '600px', margin: '0 auto', padding: 'var(--space-8) var(--space-4)', minHeight: '100vh' }}
    >
      <button onClick={onBack} style={{ background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--color-text-secondary)', marginBottom: 'var(--space-6)', padding: 0 }} className="text-label">
        <lucide.ArrowLeft size={16} /> Back to Dashboard
      </button>

      <h2 className="text-display" style={{ marginBottom: 'var(--space-2)' }}>Define Your Path</h2>
      <p className="text-body" style={{ color: 'var(--color-text-secondary)', marginBottom: 'var(--space-6)' }}>Provide your starting point and destination to anchor the map.</p>

      <div style={{ background: 'var(--color-surface)', padding: 'var(--space-5)', borderRadius: '8px', border: '1px solid var(--color-border)' }}>
        <InputField 
          label="Current State" 
          placeholder="e.g., Sophomore majoring in Biology, unsure of career path..." 
          value={current} 
          onChange={setCurrent} 
          multiline
        />
        <InputField 
          label="Target State" 
          placeholder="e.g., Accepted into a top-tier Public Health Master's program..." 
          value={target} 
          onChange={setTarget} 
          multiline
        />

        <div style={{ marginBottom: 'var(--space-5)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 'var(--space-2)' }}>
            <label htmlFor={sliderId} className="text-label" style={{ color: 'var(--color-text-secondary)' }}>Timeline Preference</label>
