          />
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 'var(--space-1)', color: 'var(--color-text-tertiary)' }} className="text-data">
            <span>3m</span>
            <span>48m</span>
          </div>
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-3)' }}>
          <Button variant="ghost" onClick={() => alert('Constraints not implemented.')}>Add Constraints</Button>
          <Button onClick={handleGenerate} status={btnStatus}>Generate Trajectory</Button>
        </div>
      </div>
    </motion.div>
  );
};

const CalculatingState = ({ setupData, onSuccess, onCancel }) => {
  const [statusText, setStatusText] = useState("Analyzing pathways...");
  const [error, setError] = useState(null);

  const statuses = [
    "Analyzing pathways...",
    "Evaluating prerequisites...",
    "Calculating milestones...",
    "Structuring timeline...",
    "Finalizing trajectory map..."
  ];

  useEffect(() => {
    let index = 0;
    const interval = setInterval(() => {
      index = (index + 1) % statuses.length;
      setStatusText(statuses[index]);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let isMounted = true;

    const generateTrajectory = async () => {
      try {
        const prompt = `
          You are an expert academic and career advisor at NU. 
          A student has provided the following context:
          Current State: "${setupData.current}"
          Target State: "${setupData.target}"
          Desired Timeline: ${setupData.timeline} months.

          Generate a realistic, step-by-step trajectory to help them bridge this gap.
          Return ONLY a valid JSON array of objects. Do not include markdown formatting, backticks, or any other text.
          Each object must have exactly these keys:
          - sequence_order (number, starting at 1)
          - title (string, short milestone name)
          - description (string, 1-2 sentences explaining the milestone)
          - estimated_time_to_complete (string, e.g., "2 months")
          - prerequisites (array of strings, what needs to be done before this)
          - action_items (array of strings, 2-3 specific tasks to complete this milestone)
          - status (string, always "pending")

          Create between 4 and 6 milestones.
        `;

        const res = await fetch('/api/ai/gemini-compat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
          body: JSON.stringify({
            model: 'gemini-3.1-pro-preview',
            messages: [
              { role: 'system', content: 'You are a helpful assistant that outputs strictly valid JSON arrays.' },
              { role: 'user', content: prompt }
            ],
            temperature: 0.3,
            max_tokens: 1500,
          }),
        });

        if (!res.ok) throw new Error('API request failed');

        const data = await res.json();
        let content = data?.choices?.[0]?.message?.content;

        if (!content) throw new Error('Empty response from AI');

        // Clean up potential markdown wrapping
        content = content.replace(/```json/g, '').replace(/```/g, '').trim();

        const parsedNodes = JSON.parse(content);

        if (!Array.isArray(parsedNodes) || parsedNodes.length === 0) {
          throw new Error('Invalid JSON structure returned');
        }

        if (isMounted) {
          // Add a slight delay to ensure the user sees the "Finalizing" state
          setTimeout(() => onSuccess(parsedNodes), 1000);
        }

      } catch (err) {
        console.error("AI Generation Error:", err);
        if (isMounted) {
          setError("Failed to generate trajectory. Using fallback data for demonstration.");
          setTimeout(() => onSuccess(FALLBACK_TRAJECTORY), 3000);
        }
      }
    };

    generateTrajectory();

    return () => { isMounted = false; };
  }, [setupData, onSuccess]);

  return (
    <motion.div 
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', padding: 'var(--space-4)' }}
    >
      <div style={{ position: 'relative', width: '120px', height: '120px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 'var(--space-6)' }}>
        <motion.div
          animate={{ scale: [1, 1.5, 1], opacity: [0.5, 0, 0.5] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
          style={{ position: 'absolute', width: '100%', height: '100%', borderRadius: '50%', backgroundColor: 'var(--color-primary)', opacity: 0.2 }}
        />
        <motion.div
          animate={{ scale: [1, 1.2, 1] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut", delay: 0.2 }}
          style={{ position: 'absolute', width: '60%', height: '60%', borderRadius: '50%', backgroundColor: 'var(--color-primary)', opacity: 0.5 }}
        />
        <div style={{ width: '20%', height: '20%', borderRadius: '50%', backgroundColor: 'var(--color-primary)', zIndex: 1 }} />
      </div>

      <div style={{ height: '40px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <AnimatePresence mode="wait">
          <motion.p
            key={statusText}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.3 }}
            className="text-label"
            style={{ color: 'var(--color-text-secondary)', margin: 0 }}
          >
            {statusText}
          </motion.p>
        </AnimatePresence>
      </div>

      {error && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ marginTop: 'var(--space-4)', color: 'var(--color-warning)', backgroundColor: '#FFF3E0', padding: '8px 16px', borderRadius: '4px' }} className="text-data">
          {error}
        </motion.div>
      )}

      <Button variant="ghost" onClick={onCancel} style={{ marginTop: 'var(--space-8)' }}>Cancel Generation</Button>
    </motion.div>
  );
};

const TrajectoryNode = ({ node, index, isActive, onClick }) => {
  const [isHovered, setIsHovered] = useState(false);

  let borderColor = 'var(--color-border)';
  let borderWidth = '2px';
  let borderStyle = 'solid';
  let bgColor = 'var(--color-bg)';
  let textColor = 'var(--color-text-primary)';
  let scale = 1;
  let glow = 'none';
  let content = index + 1;
  let isShimmer = false;

  if (node.status === 'loading') {
    isShimmer = true;
    content = '';
  } else if (node.status === 'empty') {
    borderStyle = 'dashed';
    bgColor = 'transparent';
    content = '';
  } else if (node.status === 'error') {
    borderColor = 'var(--color-error)';
    content = <lucide.AlertCircle size={20} color="var(--color-error)" />;
  } else if (node.status === 'success') {
    bgColor = 'var(--color-success)';
    borderColor = 'var(--color-success)';
    textColor = '#FFFFFF';
    content = <lucide.Check size={20} />;
  } else {
    // default / pending
    if (isActive) {
      bgColor = 'var(--color-primary)';
      borderColor = 'var(--color-primary)';
      textColor = '#FFFFFF';
      scale = 1.1;
      glow = '0 0 15px rgba(192, 0, 0, 0.4)';
    } else if (isHovered) {
      borderWidth = '4px';
      borderColor = 'var(--color-text-tertiary)';
      scale = 1.05;
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', position: 'relative', zIndex: 2, width: '160px' }}>
      <motion.button
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={() => onClick(node)}
        animate={{ scale, backgroundColor: bgColor, borderColor, borderWidth, boxShadow: glow }}
        transition={{ duration: 0.2 }}
        className={isShimmer ? 'shimmer' : ''}
        style={{
          width: '48px',
          height: '48px',
          borderRadius: '50%',
          borderStyle,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          marginBottom: 'var(--space-3)',
          color: textColor,
          fontWeight: 'bold',
          fontFamily: 'var(--font-data)',
          padding: 0,
          outline: 'none'
        }}
        aria-label={`Milestone ${index + 1}: ${node.title}`}
      >
        {content}
      </motion.button>

      {/* Tooltip */}
      <AnimatePresence>
        {isHovered && !isActive && (
          <motion.div
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 5 }}
            style={{
              position: 'absolute',
              top: '-40px',
              backgroundColor: 'var(--color-text-primary)',
              color: 'var(--color-bg)',
              padding: '4px 8px',
              borderRadius: '4px',
              fontSize: '12px',
              whiteSpace: 'nowrap',
              pointerEvents: 'none',
              zIndex: 10
            }}
            className="text-data"
          >
            Click for details
          </motion.div>
        )}
      </AnimatePresence>

      <div style={{ textAlign: 'center' }}>
        <h4 className="text-label" style={{ marginBottom: 'var(--space-1)', color: isActive ? 'var(--color-primary)' : 'var(--color-text-primary)' }}>{node.title}</h4>
        <span className="text-data" style={{ color: 'var(--color-text-tertiary)', fontSize: '12px' }}>{node.estimated_time_to_complete}</span>
      </div>
    </div>
  );
};

const InteractiveMap = ({ nodes, onNodeSelect, activeNodeId, setupData }) => {
  const containerRef = useRef(null);
  const totalDuration = nodes.reduce((acc, curr) => {
    // Rough extraction of numbers for a summary metric
    const match = curr.estimated_time_to_complete.match(/\d+/);
    return acc + (match ? parseInt(match[0]) : 0);
  }, 0);

  return (
    <motion.div 
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: 'var(--color-surface)' }}
    >
      {/* Header / Summary */}
      <div style={{ padding: 'var(--space-4) var(--space-6)', backgroundColor: 'var(--color-bg)', borderBottom: '1px solid var(--color-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', zIndex: 10 }}>
        <div>
          <h2 className="text-display" style={{ fontSize: '32px', marginBottom: 'var(--space-1)' }}>Trajectory Map</h2>
          <p className="text-body" style={{ color: 'var(--color-text-secondary)', margin: 0 }}>
            From: <span style={{ fontWeight: 600 }}>{setupData?.current?.substring(0, 30) || 'Start'}...</span> &rarr; To: <span style={{ fontWeight: 600 }}>{setupData?.target?.substring(0, 30) || 'Goal'}...</span>
          </p>
