            <div className="text-data" style={{ fontSize: '18px', fontWeight: 'bold' }}>~{totalDuration || setupData?.timeline} months</div>
          </div>
          <Button variant="ghost"><lucide.Download size={16} /> Export</Button>
        </div>
      </div>

      {/* Canvas */}
      <div 
        ref={containerRef}
        className="map-container"
        style={{ flex: 1, position: 'relative', overflowX: 'auto', overflowY: 'hidden', display: 'flex', alignItems: 'center', padding: '0 var(--space-8)' }}
      >
        <div style={{ display: 'flex', alignItems: 'center', position: 'relative', minWidth: 'max-content', padding: 'var(--space-8) 0' }}>

          {/* Connecting Lines (SVG) */}
          <svg style={{ position: 'absolute', top: '50%', left: '80px', right: '80px', height: '4px', width: `calc(100% - 160px)`, transform: 'translateY(-50%)', zIndex: 1, overflow: 'visible' }}>
            {nodes.map((_, i) => {
              if (i === nodes.length - 1) return null;
              return (
                <motion.line
                  key={`line-${i}`}
                  x1={`${(i / (nodes.length - 1)) * 100}%`}
                  y1="2"
                  x2={`${((i + 1) / (nodes.length - 1)) * 100}%`}
                  y2="2"
                  stroke="var(--color-border)"
                  strokeWidth="2"
                  initial={{ pathLength: 0 }}
                  animate={{ pathLength: 1 }}
                  transition={{ duration: 0.8, delay: i * 0.4, ease: "easeInOut" }}
                />
              );
            })}
            {/* Active Path Overlay */}
            {activeNodeId && (
              <motion.line
                x1="0%"
                y1="2"
                x2={`${(nodes.findIndex(n => n.title === activeNodeId) / (nodes.length - 1)) * 100}%`}
                y2="2"
                stroke="var(--color-primary)"
                strokeWidth="3"
                style={{ filter: 'drop-shadow(0 0 6px rgba(192,0,0,0.6))' }}
                initial={{ pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{ duration: 0.4 }}
              />
            )}
          </svg>

          {/* Nodes */}
          {nodes.map((node, i) => (
            <div key={i} style={{ marginRight: i === nodes.length - 1 ? 0 : '120px' }}>
              <TrajectoryNode 
                node={node} 
                index={i} 
                isActive={activeNodeId === node.title} 
                onClick={onNodeSelect} 
              />
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  );
};

const NodeInspector = ({ node, onClose, onMarkComplete }) => {
