            disabled={node.status === 'success'}
          >
            {node.status === 'success' ? 'Milestone Reached' : 'Mark as Reached'}
          </Button>
          <Button variant="ghost" style={{ width: '100%', marginTop: 'var(--space-2)' }}>View Resources</Button>
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

// --- Main App Component ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('dashboard_empty');
  const [setupData, setSetupData] = useState({ current: '', target: '', timeline: 12 });
  const [trajectoryNodes, setTrajectoryNodes] = useState([]);
  const [activeNodeId, setActiveNodeId] = useState(null);

  useEffect(() => {
    injectStyles();
  }, []);

  // State Machine Handlers
  const handleStartNew = () => setCurrentScreen('trajectory_setup');

  const handleGenerate = (data) => {
    setSetupData(data);
    setCurrentScreen('calculating_state');
  };

  const handleGenerationSuccess = (nodes) => {
    setTrajectoryNodes(nodes);
    setCurrentScreen('interactive_map');
  };

  const handleCancelGeneration = () => setCurrentScreen('trajectory_setup');

  const handleNodeSelect = (node) => setActiveNodeId(node.title);

  const handleCloseInspector = () => setActiveNodeId(null);

  const handleMarkComplete = (nodeTitle) => {
    setTrajectoryNodes(prev => prev.map(n => 
      n.title === nodeTitle ? { ...n, status: 'success' } : n
    ));
  };

  // Demo Controls
  const DemoControls = () => (
    <div style={{ position: 'fixed', top: 10, right: 10, zIndex: 9999, background: 'rgba(0,0,0,0.8)', padding: '8px', borderRadius: '4px', display: 'flex', gap: '4px', color: 'white', fontFamily: 'monospace', fontSize: '10px' }}>
      <span style={{ padding: '4px', opacity: 0.5 }}>DEMO:</span>
      {['dashboard_empty', 'trajectory_setup', 'calculating_state', 'interactive_map'].map(s => (
        <button 
          key={s} 
          onClick={() => {
            if (s === 'interactive_map' && trajectoryNodes.length === 0) {
              setTrajectoryNodes(FALLBACK_TRAJECTORY);
            }
            setCurrentScreen(s);
            setActiveNodeId(null);
          }}
          style={{ background: currentScreen === s ? 'var(--color-primary)' : '#333', color: 'white', border: 'none', padding: '4px 8px', cursor: 'pointer', borderRadius: '2px' }}
        >
          {s.split('_')[0]}
        </button>
      ))}
    </div>
  );

  return (
    <div style={{ position: 'relative', minHeight: '100vh', overflow: 'hidden' }}>
      <DemoControls />

      <AnimatePresence mode="wait">
        {currentScreen === 'dashboard_empty' && (
          <DashboardEmpty key="dashboard" onStart={handleStartNew} />
        )}

        {currentScreen === 'trajectory_setup' && (
          <TrajectorySetup key="setup" onGenerate={handleGenerate} onBack={() => setCurrentScreen('dashboard_empty')} />
        )}

        {currentScreen === 'calculating_state' && (
          <CalculatingState key="calc" setupData={setupData} onSuccess={handleGenerationSuccess} onCancel={handleCancelGeneration} />
        )}

        {currentScreen === 'interactive_map' && (
          <InteractiveMap key="map" nodes={trajectoryNodes} onNodeSelect={handleNodeSelect} activeNodeId={activeNodeId} setupData={setupData} />
        )}
      </AnimatePresence>

      {/* Overlay for Inspector */}
      <AnimatePresence>
        {activeNodeId && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={handleCloseInspector}
            style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.2)', zIndex: 40 }}
          />
        )}
      </AnimatePresence>

      <NodeInspector 
        node={trajectoryNodes.find(n => n.title === activeNodeId)} 
        onClose={handleCloseInspector} 
        onMarkComplete={handleMarkComplete}
      />
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

export default App;

