    <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
      <Button onClick={onStart}>Start New Trajectory <lucide.ArrowRight size={16} /></Button>
      <Button variant="ghost" onClick={() => alert('Sample trajectories not implemented in this prototype.')}>View Samples</Button>
    </div>
  </motion.div>
);

const TrajectorySetup = ({ onGenerate, onBack }) => {
  const [current, setCurrent] = useState('');
