    if (!current || !target) {
      setBtnStatus('error');
      setTimeout(() => setBtnStatus('default'), 2000);
      return;
    }
    setBtnStatus('loading');
    // Simulate a brief local delay before handing off to the calculating screen
    setTimeout(() => {
      onGenerate({ current, target, timeline });
