  return (
    <AnimatePresence>
      <motion.div
        initial={{ x: '100%', boxShadow: '-10px 0 30px rgba(0,0,0,0)' }}
        animate={{ x: 0, boxShadow: '-10px 0 30px rgba(0,0,0,0.1)' }}
        exit={{ x: '100%', boxShadow: '-10px 0 30px rgba(0,0,0,0)' }}
        transition={{ type: 'spring', damping: 25, stiffness: 200 }}
        style={{
          position: 'fixed',
          top: 0,
          right: 0,
          bottom: 0,
          width: '400px',
          backgroundColor: 'var(--color-bg)',
          borderLeft: '1px solid var(--color-border)',
          zIndex: 50,
          display: 'flex',
          flexDirection: 'column',
          overflowY: 'auto'
        }}
      >
        <div style={{ padding: 'var(--space-4)', borderBottom: '1px solid var(--color-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', backgroundColor: 'var(--color-surface)' }}>
          <div>
            <div className="text-data" style={{ color: 'var(--color-primary)', marginBottom: 'var(--space-1)' }}>Milestone {node.sequence_order}</div>
            <h3 className="text-display" style={{ fontSize: '28px', lineHeight: 1 }}>{node.title}</h3>
          </div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-secondary)', padding: '4px' }}>
            <lucide.X size={24} />
          </button>
        </div>

        <div style={{ padding: 'var(--space-4)', flex: 1 }}>
          <div style={{ display: 'flex', gap: 'var(--space-2)', marginBottom: 'var(--space-4)' }}>
            <span style={{ padding: '4px 8px', backgroundColor: 'var(--color-panel)', borderRadius: '4px', display: 'inline-flex', alignItems: 'center', gap: '4px' }} className="text-data">
              <lucide.Clock size={14} /> {node.estimated_time_to_complete}
            </span>
            <span style={{ padding: '4px 8px', backgroundColor: node.status === 'success' ? '#E6F9F0' : 'var(--color-panel)', color: node.status === 'success' ? 'var(--color-success)' : 'inherit', borderRadius: '4px', display: 'inline-flex', alignItems: 'center', gap: '4px' }} className="text-data">
              {node.status === 'success' ? <lucide.CheckCircle size={14} /> : <lucide.Circle size={14} />} 
              {node.status.charAt(0).toUpperCase() + node.status.slice(1)}
            </span>
          </div>

          <p className="text-body" style={{ marginBottom: 'var(--space-5)' }}>{node.description}</p>

          <h4 className="text-label" style={{ marginBottom: 'var(--space-2)', color: 'var(--color-text-secondary)' }}>Prerequisites</h4>
          <ul style={{ paddingLeft: 'var(--space-4)', marginBottom: 'var(--space-5)', marginTop: 0 }} className="text-body">
            {node.prerequisites?.map((req, i) => <li key={i} style={{ marginBottom: 'var(--space-1)' }}>{req}</li>)}
            {(!node.prerequisites || node.prerequisites.length === 0) && <li style={{ color: 'var(--color-text-tertiary)' }}>None</li>}
          </ul>

          <h4 className="text-label" style={{ marginBottom: 'var(--space-2)', color: 'var(--color-text-secondary)' }}>Action Items</h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', marginBottom: 'var(--space-6)' }}>
            {node.action_items?.map((item, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--space-2)', padding: 'var(--space-3)', backgroundColor: 'var(--color-surface)', borderRadius: '4px', border: '1px solid var(--color-border)' }}>
                <div style={{ marginTop: '2px', color: 'var(--color-primary)' }}><lucide.ArrowRight size={16} /></div>
                <span className="text-body" style={{ margin: 0 }}>{item}</span>
              </div>
            ))}
          </div>
        </div>

        <div style={{ padding: 'var(--space-4)', borderTop: '1px solid var(--color-border)', backgroundColor: 'var(--color-surface)' }}>
          <Button 
            onClick={() => onMarkComplete(node.title)} 
            style={{ width: '100%' }}
            status={node.status === 'success' ? 'success' : 'default'}
            disabled={node.status === 'success'}
          >
            {node.status === 'success' ? 'Milestone Reached' : 'Mark as Reached'}
          </Button>
          <Button variant="ghost" style={{ width: '100%', marginTop: 'var(--space-2)' }}>View Resources</Button>
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

// --- Main App Component ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('dashboard_empty');
  const [setupData, setSetupData] = useState({ current: '', target: '', timeline: 12 });
  const [trajectoryNodes, setTrajectoryNodes] = useState([]);
  const [activeNodeId, setActiveNodeId] = useState(null);

  useEffect(() => {
    injectStyles();
  }, []);

  // State Machine Handlers
  const handleStartNew = () => setCurrentScreen('trajectory_setup');

  const handleGenerate = (data) => {
    setSetupData(data);
    setCurrentScreen('calculating_state');
  };

  const handleGenerationSuccess = (nodes) => {
    setTrajectoryNodes(nodes);
    setCurrentScreen('interactive_map');
  };

  const handleCancelGeneration = () => setCurrentScreen('trajectory_setup');

  const handleNodeSelect = (node) => setActiveNodeId(node.title);

  const handleCloseInspector = () => setActiveNodeId(null);

  const handleMarkComplete = (nodeTitle) => {
    setTrajectoryNodes(prev => prev.map(n => 
      n.title === nodeTitle ? { ...n, status: 'success' } : n
    ));
  };

  // Demo Controls
  const DemoControls = () => (
    <div style={{ position: 'fixed', top: 10, right: 10, zIndex: 9999, background: 'rgba(0,0,0,0.8)', padding: '8px', borderRadius: '4px', display: 'flex', gap: '4px', color: 'white', fontFamily: 'monospace', fontSize: '10px' }}>
      <span style={{ padding: '4px', opacity: 0.5 }}>DEMO:</span>
      {['dashboard_empty', 'trajectory_setup', 'calculating_state', 'interactive_map'].map(s => (
        <button 
          key={s} 
          onClick={() => {
            if (s === 'interactive_map' && trajectoryNodes.length === 0) {
              setTrajectoryNodes(FALLBACK_TRAJECTORY);
            }
            setCurrentScreen(s);
            setActiveNodeId(null);
          }}
          style={{ background: currentScreen === s ? 'var(--color-primary)' : '#333', color: 'white', border: 'none', padding: '4px 8px', cursor: 'pointer', borderRadius: '2px' }}
        >
          {s.split('_')[0]}
        </button>
      ))}
    </div>
  );

  return (
    <div style={{ position: 'relative', minHeight: '100vh', overflow: 'hidden' }}>
      <DemoControls />

      <AnimatePresence mode="wait">
        {currentScreen === 'dashboard_empty' && (
          <DashboardEmpty key="dashboard" onStart={handleStartNew} />
        )}

        {currentScreen === 'trajectory_setup' && (
          <TrajectorySetup key="setup" onGenerate={handleGenerate} onBack={() => setCurrentScreen('dashboard_empty')} />
        )}

        {currentScreen === 'calculating_state' && (
          <CalculatingState key="calc" setupData={setupData} onSuccess={handleGenerationSuccess} onCancel={handleCancelGeneration} />
        )}

        {currentScreen === 'interactive_map' && (
          <InteractiveMap key="map" nodes={trajectoryNodes} onNodeSelect={handleNodeSelect} activeNodeId={activeNodeId} setupData={setupData} />
        )}
      </AnimatePresence>

      {/* Overlay for Inspector */}
      <AnimatePresence>
        {activeNodeId && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={handleCloseInspector}
            style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.2)', zIndex: 40 }}
          />
        )}
      </AnimatePresence>

      <NodeInspector 
        node={trajectoryNodes.find(n => n.title === activeNodeId)} 
        onClose={handleCloseInspector} 
        onMarkComplete={handleMarkComplete}
      />
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

export default App;
